import { randomBytes } from "node:crypto";
import {
  DynamoDBClient,
  GetItemCommand,
  PutItemCommand,
  DeleteItemCommand,
  UpdateItemCommand,
  QueryCommand,
} from "@aws-sdk/client-dynamodb";
import { KEYS, bucketOf, getObject, getJson, headObject } from "./store.mjs";
import { collectionUrl, resourceUrl, CONTENT_META } from "./meta.mjs";
import { originId } from "./service.mjs";
import { invalidRequestBody } from "./problems.mjs";

// The `changes` query profile's feed (PWS v0.5, Query Profile Registry):
// per Collection, one entry per record at the position of its latest
// write, ordered by a server-assigned position, with tombstones for deleted
// Resources and policies and entries for the Collection Metadata object and
// the governing history log.
//
// S3 stays the system of record. The feed is a DynamoDB projection fed by
// the bucket's object events (S3 to EventBridge to a FIFO queue to the
// consumer function, src/feed/consumer), which assign positions in order
// from a per-Collection counter and write one row per record. A query
// reads the rows after a checkpoint and hydrates each from the object's
// live state, so an entry's `etag` and `data` are what a read of the
// Resource answers at that moment. A sweep (src/feed/sweep) repairs rows
// an event never reached.
//
// Table `pws-feed`: PK `bucket` (the Space's bucket name), SK `record`
// (`{collection}#{kind}#{recordId}`); each row carries `feed`
// (`{bucket}/{collection}`) and `position` for the `by-position` index the
// query reads. The per-Collection counter is the row `{collection}#`,
// holding `next` and the feed's `generation` (fresh when a Collection is
// re-created, so an old checkpoint is refused).

const TABLE = process.env.FEED_TABLE_NAME ?? "pws-feed";
const INDEX = "by-position";
const dynamo = new DynamoDBClient({});

export const KINDS = ["resource", "collection-metadata", "log", "policy"];

export const feedOf = (bucket, collectionId) => `${bucket}/${collectionId}`;
const recordSk = (collectionId, kind, recordId) => `${collectionId}#${kind}#${recordId}`;
const counterSk = (collectionId) => `${collectionId}#`;

const quoted = (etag) => (etag === undefined || etag === null ? undefined : /^"/.test(etag) ? etag : `"${etag}"`);

// What an object key is to the feed: the Collection, the record kind and
// id, and whether the key is a Resource's metadata sidecar (a change of
// the Resource's entry, not a record of its own). Null for keys outside the
// feed (Space-level objects).
export function classifyKey(key) {
  let match;
  if ((match = /^collections\/([^/]+)\/(.+)$/.exec(key))) {
    return { collectionId: match[1], kind: "resource", recordId: match[2] };
  }
  if ((match = /^meta\/([^/]+)\/(.+)\.json$/.exec(key))) {
    return { collectionId: match[1], kind: "resource", recordId: match[2], sidecar: true };
  }
  if ((match = /^meta\/([^/]+)\.json$/.exec(key)) && match[1] !== "space") {
    return { collectionId: match[1], kind: "collection-metadata", recordId: "" };
  }
  if ((match = /^meta\/([^/]+)\.log$/.exec(key))) {
    return { collectionId: match[1], kind: "log", recordId: "" };
  }
  if ((match = /^policies\/([^/]+)\/(.+)\.json$/.exec(key))) {
    return { collectionId: match[1], kind: "policy", recordId: match[2] };
  }
  if ((match = /^policies\/([^/]+)\.json$/.exec(key)) && match[1] !== "space") {
    return { collectionId: match[1], kind: "policy", recordId: "" };
  }
  return null;
}

// The S3 object key a feed record stands for.
export function keyOfRecord(collectionId, kind, recordId) {
  switch (kind) {
    case "resource":
      return KEYS.resource(collectionId, recordId);
    case "collection-metadata":
      return KEYS.collectionMeta(collectionId);
    case "log":
      return KEYS.collectionLog(collectionId);
    case "policy":
      return recordId ? KEYS.resourcePolicy(collectionId, recordId) : KEYS.collectionPolicy(collectionId);
    default:
      return null;
  }
}

const item = (bucket, record) => ({ bucket: { S: bucket }, record: { S: record } });

const fromItem = (it) =>
  it && {
    bucket: it.bucket.S,
    record: it.record.S,
    feed: it.feed?.S,
    collectionId: it.collectionId?.S,
    kind: it.kind?.S,
    recordId: it.recordId?.S ?? "",
    position: Number(it.position?.N ?? 0),
    deleted: it.deleted?.BOOL ?? false,
    updatedAt: it.updatedAt?.S,
    sequencer: it.sequencer?.S,
    etag: it.etag?.S,
    contentType: it.contentType?.S,
  };

async function getRow(bucket, record) {
  const out = await dynamo.send(new GetItemCommand({ TableName: TABLE, Key: item(bucket, record) }));
  return fromItem(out.Item) ?? null;
}

export async function readCounter(bucket, collectionId) {
  const out = await dynamo.send(new GetItemCommand({ TableName: TABLE, Key: item(bucket, counterSk(collectionId)) }));
  return out.Item ? { next: Number(out.Item.next?.N ?? 0), generation: out.Item.generation?.S } : null;
}

// The next position of a Collection's feed, minting the feed's generation
// on first use.
async function allocatePosition(bucket, collectionId) {
  const out = await dynamo.send(
    new UpdateItemCommand({
      TableName: TABLE,
      Key: item(bucket, counterSk(collectionId)),
      UpdateExpression: "ADD #n :one SET #g = if_not_exists(#g, :gen), #c = :collection",
      ExpressionAttributeNames: { "#n": "next", "#g": "generation", "#c": "collectionId" },
      ExpressionAttributeValues: {
        ":one": { N: "1" },
        ":gen": { S: randomBytes(9).toString("base64url") },
        ":collection": { S: collectionId },
      },
      ReturnValues: "ALL_NEW",
    })
  );
  return { position: Number(out.Attributes.next.N), generation: out.Attributes.generation.S };
}

// S3 sequencers order the events of one key: hexadecimal strings compared
// after padding the shorter with zeros on the right.
export function laterSequencer(a, b) {
  if (a === undefined || b === undefined) {
    return true;
  }
  const length = Math.max(a.length, b.length);
  return a.padEnd(length, "0") > b.padEnd(length, "0");
}

// Applies one object event to the feed: the record moves to the next
// position (a stale event, or one that changes nothing, is skipped), a
// Resource or policy delete becomes a tombstone, and the delete of a
// Collection's metadata object drops the Collection's whole feed. Resolves
// to what happened, for the consumer's log.
export async function applyObjectEvent({ bucket, key, deleted, etag, sequencer, time, contentType }) {
  const classified = classifyKey(key);
  if (classified === null) {
    return { outcome: "ignored" };
  }
  const { collectionId, kind, recordId, sidecar } = classified;
  if (kind === "collection-metadata" && deleted) {
    await purgeCollection(bucket, collectionId);
    return { outcome: "purged", collectionId };
  }
  const record = recordSk(collectionId, kind, recordId);
  const current = await getRow(bucket, record);
  if (current !== null && sequencer !== undefined && current.sequencer !== undefined && !laterSequencer(sequencer, current.sequencer)) {
    return { outcome: "stale", record };
  }
  let next;
  if (sidecar) {
    // A metadata-only edit re-surfaces the Resource; a sidecar of a Resource
    // that is gone changes nothing
    const head = await headObject(bucket, KEYS.resource(collectionId, recordId));
    if (head === null) {
      return { outcome: "orphan", record };
    }
    next = { deleted: false, etag: quoted(head.etag), contentType: head.contentType };
  } else if (deleted) {
    next = { deleted: true, etag: undefined, contentType: current?.contentType };
  } else {
    next = { deleted: false, etag: quoted(etag), contentType };
    if (kind === "resource" && next.contentType === undefined) {
      const head = await headObject(bucket, key);
      if (head === null) {
        // Deleted again since the event; the delete's own event follows
        return { outcome: "gone", record };
      }
      next.contentType = head.contentType;
      next.etag = quoted(head.etag);
    }
  }
  if (current !== null && sequencer === undefined && current.deleted === next.deleted && current.etag === next.etag && !sidecar) {
    return { outcome: "unchanged", record };
  }
  const { position, generation } = await allocatePosition(bucket, collectionId);
  await dynamo.send(
    new PutItemCommand({
      TableName: TABLE,
      Item: {
        ...item(bucket, record),
        feed: { S: feedOf(bucket, collectionId) },
        collectionId: { S: collectionId },
        kind: { S: kind },
        recordId: { S: recordId },
        position: { N: String(position) },
        deleted: { BOOL: next.deleted },
        updatedAt: { S: time ?? new Date().toISOString() },
        ...(sequencer !== undefined && { sequencer: { S: sequencer } }),
        ...(next.etag !== undefined && { etag: { S: next.etag } }),
        ...(next.contentType !== undefined && { contentType: { S: next.contentType } }),
      },
    })
  );
  return { outcome: "positioned", record, position, generation };
}

async function queryAll(input) {
  const rows = [];
  let cursor;
  do {
    const out = await dynamo.send(new QueryCommand({ ...input, ...(cursor && { ExclusiveStartKey: cursor }) }));
    rows.push(...(out.Items ?? []));
    cursor = out.LastEvaluatedKey;
  } while (cursor);
  return rows;
}

// Drops every row of a Collection's feed, its counter included.
export async function purgeCollection(bucket, collectionId) {
  const rows = await queryAll({
    TableName: TABLE,
    KeyConditionExpression: "#b = :bucket AND begins_with(#r, :prefix)",
    ExpressionAttributeNames: { "#b": "bucket", "#r": "record" },
    ExpressionAttributeValues: { ":bucket": { S: bucket }, ":prefix": { S: `${collectionId}#` } },
  });
  for (const row of rows) {
    await dynamo.send(new DeleteItemCommand({ TableName: TABLE, Key: item(bucket, row.record.S) }));
  }
  return rows.length;
}

// Drops every feed row of a bucket (a deleted Space).
export async function purgeBucket(bucket) {
  const rows = await queryAll({
    TableName: TABLE,
    KeyConditionExpression: "#b = :bucket",
    ExpressionAttributeNames: { "#b": "bucket" },
    ExpressionAttributeValues: { ":bucket": { S: bucket } },
  });
  for (const row of rows) {
    await dynamo.send(new DeleteItemCommand({ TableName: TABLE, Key: item(bucket, row.record.S) }));
  }
  return rows.length;
}

// The rows of a Collection's feed after a position, in order.
export async function readFeedRows(bucket, collectionId, { after, limit }) {
  const out = await dynamo.send(
    new QueryCommand({
      TableName: TABLE,
      IndexName: INDEX,
      KeyConditionExpression: "#f = :feed AND #p > :after",
      ExpressionAttributeNames: { "#f": "feed", "#p": "position" },
      ExpressionAttributeValues: { ":feed": { S: feedOf(bucket, collectionId) }, ":after": { N: String(after) } },
      Limit: limit,
    })
  );
  return { rows: (out.Items ?? []).map(fromItem), more: out.LastEvaluatedKey !== undefined };
}

// Every row of a Collection's feed, for the sweep.
export async function allFeedRows(bucket, collectionId) {
  const rows = await queryAll({
    TableName: TABLE,
    KeyConditionExpression: "#b = :bucket AND begins_with(#r, :prefix)",
    ExpressionAttributeNames: { "#b": "bucket", "#r": "record" },
    ExpressionAttributeValues: { ":bucket": { S: bucket }, ":prefix": { S: `${collectionId}#` } },
  });
  return rows.map(fromItem).filter((row) => row.kind !== undefined);
}

// --- checkpoints ----------------------------------------------------------------

// An opaque string scoped to the server and the Collection: the feed's
// URL, its generation and a position, base64url-encoded JSON (the
// reference server's encoding, which a client never reads).
export function encodeCheckpoint({ feed, generation, position }) {
  return Buffer.from(JSON.stringify({ feed, generation, position }), "utf8").toString("base64url");
}

export function decodeCheckpoint(value, { feed, generation }) {
  const refuse = () =>
    invalidRequestBody("The checkpoint was not issued by this server for this Collection.", {
      errors: [{ detail: "The checkpoint was not issued by this server for this Collection.", pointer: "#/checkpoint" }],
    });
  if (typeof value !== "string" || value.length === 0) {
    throw refuse();
  }
  let parsed;
  try {
    parsed = JSON.parse(Buffer.from(value, "base64url").toString("utf8"));
  } catch {
    throw refuse();
  }
  if (
    typeof parsed !== "object" ||
    parsed === null ||
    Object.keys(parsed).sort().join() !== "feed,generation,position" ||
    parsed.feed !== feed ||
    parsed.generation !== generation ||
    !Number.isSafeInteger(parsed.position) ||
    parsed.position < 0
  ) {
    throw refuse();
  }
  return parsed.position;
}

// --- the page ---------------------------------------------------------------

const DEFAULT_LIMIT = 100;
const MAX_LIMIT = 1000;

export function pageLimitOf(value) {
  const limit = Number(value);
  if (!Number.isFinite(limit) || limit < 1) {
    return DEFAULT_LIMIT;
  }
  return Math.min(Math.trunc(limit), MAX_LIMIT);
}

const generationOf = (etag) => (etag ?? "").replace(/"/g, "").split(".")[0] || "none";

const stamp = (row, updatedAt) => ({
  updatedAt: updatedAt ?? row.updatedAt,
  updatedAtCounter: row.position,
  originId: originId(),
});

// One feed entry from a row and the record's live state, or null when the
// record is gone without a tombstone (a purged Collection's stragglers).
async function hydrate(req, { spaceId, collectionId, row, checkpoint }) {
  const base = collectionUrl(req, spaceId, collectionId);
  if (row.kind === "resource") {
    const object = row.deleted ? null : await getObject(spaceId, KEYS.resource(collectionId, row.recordId));
    if (object === null) {
      return {
        kind: "resource",
        id: row.recordId,
        contentType: row.contentType ?? "application/octet-stream",
        deleted: true,
        ...stamp(row),
        generation: "deleted",
        checkpoint,
        etag: `"deleted.${row.position}"`,
      };
    }
    const meta = object.metadata ?? {};
    const contentType = object.contentType ?? "application/octet-stream";
    const sidecar = await getJson(spaceId, KEYS.resourceMeta(collectionId, row.recordId));
    let data;
    if (isJsonContentType(contentType)) {
      const text = object.body.toString("utf8");
      try {
        data = JSON.parse(text);
      } catch {
        data = text;
      }
    }
    return {
      kind: "resource",
      id: row.recordId,
      contentType,
      deleted: false,
      ...stamp(row, object.lastModified?.toISOString?.()),
      generation: generationOf(object.etag),
      checkpoint,
      etag: object.etag,
      ...(sidecar?.etag && { metaEtag: sidecar.etag }),
      ...(meta[CONTENT_META.createdBy] && { createdBy: meta[CONTENT_META.createdBy] }),
      ...(meta[CONTENT_META.epoch] && { epoch: meta[CONTENT_META.epoch] }),
      ...(meta[CONTENT_META.writerId] && { writerId: meta[CONTENT_META.writerId] }),
      ...(data !== undefined && { data }),
      ...(sidecar?.doc?.custom !== undefined && { custom: sidecar.doc.custom }),
    };
  }
  const key = keyOfRecord(collectionId, row.kind, row.recordId);
  const head = await headObject(spaceId, key);
  const id =
    row.kind === "collection-metadata"
      ? `${base}meta`
      : row.kind === "log"
        ? `${base}meta/log`
        : row.recordId
          ? `${resourceUrl(req, spaceId, collectionId, row.recordId)}/policy`
          : `${base}policy`;
  if (head === null) {
    if (row.kind !== "policy") {
      return null;
    }
    return { kind: "policy", id, deleted: true, ...stamp(row), generation: "deleted", checkpoint, etag: `"deleted.${row.position}"` };
  }
  return {
    kind: row.kind,
    id,
    deleted: false,
    ...stamp(row, head.lastModified?.toISOString?.()),
    generation: generationOf(head.etag),
    checkpoint,
    etag: head.etag,
  };
}

// A JSON Resource, whose body the feed carries as `data` (storage-core's
// reading of the media type; JSON Lines is not one JSON document).
export const isJsonContentType = (contentType) => /^application\/([^+\s;]+\+)?json\s*(;.*)?$/i.test(contentType ?? "");

// The `changes` page: the entries after the checkpoint, each with the
// checkpoint that resumes after it; `checkpoint` null at the end.
export async function changesPage(req, { spaceId, collectionId, checkpoint, limit }) {
  const bucket = bucketOf(spaceId);
  const feed = collectionUrl(req, spaceId, collectionId);
  const counter = await readCounter(bucket, collectionId);
  if (counter === null) {
    if (checkpoint !== undefined) {
      decodeCheckpoint(checkpoint, { feed, generation: undefined });
    }
    return { documents: [], checkpoint: null };
  }
  let after = checkpoint === undefined ? 0 : decodeCheckpoint(checkpoint, { feed, generation: counter.generation });
  const size = pageLimitOf(limit);
  const documents = [];
  // Rows whose record is gone are skipped; the page is refilled past them
  for (let round = 0; round < 10 && documents.length < size; round++) {
    const { rows, more } = await readFeedRows(bucket, collectionId, { after, limit: size - documents.length });
    if (rows.length === 0) {
      break;
    }
    for (const row of rows) {
      const entry = await hydrate(req, {
        spaceId,
        collectionId,
        row,
        checkpoint: encodeCheckpoint({ feed, generation: counter.generation, position: row.position }),
      });
      if (entry !== null) {
        documents.push(entry);
      }
    }
    after = rows[rows.length - 1].position;
    if (!more) {
      break;
    }
  }
  return { documents, checkpoint: documents.length ? documents[documents.length - 1].checkpoint : null };
}
